{"code": "export async function main(input) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const unresolved = issues.filter(i => i.status === "unresolved" && i.count >= 150);
  const culprits = [...new Set(unresolved.map(i => i.culprit))];
  const linearHits: Record<string, any> = {};
  for (const c of culprits) {
    const r = await sdk.linear.searchIssues({ query: c });
    linearHits[c] = r.issues.map(x => ({ id: x.id, identifier: x.identifier, title: x.title, desc: x.description }));
  }
  return { total: issues.length, unresolved: unresolved.map(i => ({ id: i.id, title: i.title, culprit: i.culprit, count: i.count, status: i.status, file: i.filename, line: i.lineNumber })), linearHits };
}"}

