{"code": "export async function main(input: any) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const qualifying = issues.filter(i => i.status === "unresolved" && i.count >= 150);
  const byCulprit = new Map<string, typeof qualifying[number]>();
  for (const i of qualifying) if (!byCulprit.has(i.culprit)) byCulprit.set(i.culprit, i);
  const out: any[] = [];
  for (const [culprit, first] of byCulprit) {
    const blame = await sdk.github.getBlame({ file: first.filename, line: first.lineNumber });
    out.push({ culprit, issueId: first.id, title: first.title, file: first.filename, line: first.lineNumber, blame });
  }
  return { checked: issues.length, qualifying: qualifying.length, out };
}"}

{"code": "export async function main(input: any) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const qualifying = issues.filter(i => i.status === "unresolved" && i.count >= 150);
  const byCulprit = new Map<string, typeof qualifying[number]>();
  for (const i of qualifying) if (!byCulprit.has(i.culprit)) byCulprit.set(i.culprit, i);

  const created: any[] = [];
  for (const [culprit, first] of byCulprit) {
    const existing = await sdk.linear.searchIssues({ query: culprit });
    if (existing.issues.length > 0) continue;
    const blame = await sdk.github.getBlame({ file: first.filename, line: first.lineNumber });
    const issue = await sdk.linear.createIssue({
      title: `[Sentry] ${first.title}`,
      description: culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push({ culprit, plannedTitle: `[Sentry] ${first.title}`, assignee: blame.authorEmail, issue });
  }
  return { checked: issues.length, createdCount: created.length, created };
}"}

